```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let mut msg = String::new();
        msg.push_str("Digest ");
        msg.push_str(&composed.date);
        msg.push('\n');
        msg.push_str(&composed.overview);
        for e in composed.entries.iter() {
            if !e.kept {
                continue;
            }
            msg.push_str("\n- ");
            msg.push_str(&e.title);
            msg.push_str(" (");
            msg.push_str(&e.link);
            msg.push(')');
            if !e.summary.is_empty() {
                msg.push_str(": ");
                msg.push_str(&e.summary);
            }
        }

        let published = notifier::notify(&msg);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
